package com.franco.desco.adapter.in.web.cultivation;
import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.cultivation.CultivationCommands;import com.franco.desco.application.cultivation.port.in.CultivationUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/cultivos") @Tag(name="Parcelas y cultivos",description="Gestión de parcelas, cultivos y expediente técnico.") @SecurityRequirement(name=OpenApiConstants.BEARER_AUTH) @Validated public class CultivationController{private final CultivationUseCase u;private final CultivationWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public CultivationController(CultivationUseCase u,CultivationWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping @PreAuthorize("@permissionGuard.has(authentication,'CULTIVOS_LISTAR')") @Operation(operationId="cultivosListar",summary="Listar parcelas y cultivos") public ResponseEntity<ApiResponse<PageResponse<CultivationResponses.Summary>>>list(@RequestParam(required=false)Long predioId,@RequestParam(required=false)Long socioId,@RequestParam(required=false)Long variedadPaltaId,@RequestParam(required=false)String situacionCultivo,@RequestParam(required=false)String buscar,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,predioId,socioId,variedadPaltaId,situacionCultivo,buscar),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/expediente") @PreAuthorize("@permissionGuard.has(authentication,'CULTIVOS_VER')") @Operation(operationId="cultivosVerExpediente",summary="Ver expediente de parcela/cultivo") public ResponseEntity<ApiResponse<CultivationResponses.Detail>>get(@RequestParam(required=false)Long parcelaId,@RequestParam(required=false)Long parcelaCultivoId,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new CultivationCommands.GetCultivation(parcelaId,parcelaCultivoId),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping("/parcelas") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'CULTIVOS_CREAR')") @Operation(operationId="parcelasCrear",summary="Registrar parcela") public ResponseEntity<ApiResponse<CultivationResponses.Created>>createPlot(@Valid@RequestBody CultivationRequests.CreatePlot q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.createPlot(new CultivationCommands.CreatePlot(q.predioId(),q.codigo(),q.nombre(),q.areaHa()),ids.resolve(a),meta.resolve(r)),r,CultivationResponses.Created::new);}
 @PutMapping("/parcelas/{id}") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'CULTIVOS_EDITAR')") @Operation(operationId="parcelasEditar",summary="Editar parcela") public ResponseEntity<ApiResponse<Void>>updatePlot(@PathVariable Long id,@Valid@RequestBody CultivationRequests.UpdatePlot q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.updatePlot(new CultivationCommands.UpdatePlot(id,q.predioId(),q.codigo(),q.nombre(),q.areaHa()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/parcelas/{id}/cultivos") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'CULTIVOS_CREAR')") @Operation(operationId="cultivosCrear",summary="Registrar cultivo") public ResponseEntity<ApiResponse<CultivationResponses.Created>>createCrop(@PathVariable Long id,@Valid@RequestBody CultivationRequests.CreateCrop q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.createCrop(new CultivationCommands.CreateCrop(id,q.variedadPaltaId(),q.fechaInicio()),ids.resolve(a),meta.resolve(r)),r,CultivationResponses.Created::new);}
 @PutMapping("/{id}") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'CULTIVOS_EDITAR')") @Operation(operationId="cultivosEditar",summary="Editar cultivo") public ResponseEntity<ApiResponse<Void>>updateCrop(@PathVariable Long id,@Valid@RequestBody CultivationRequests.UpdateCrop q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.updateCrop(new CultivationCommands.UpdateCrop(id,q.variedadPaltaId(),q.fechaInicio()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/finalizar") @IdempotentOperation @PreAuthorize("@permissionGuard.has(authentication,'CULTIVOS_CONFIRMAR')") @Operation(operationId="cultivosFinalizar",summary="Finalizar cultivo") public ResponseEntity<ApiResponse<Void>>finish(@PathVariable Long id,@Valid@RequestBody CultivationRequests.FinishCrop q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.finishCrop(new CultivationCommands.FinishCrop(id,q.fechaFin(),q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
}
